import SwiftUI
struct ContentView:View{@State private var name="Material User";@State private var notifications=true;@State private var saved=false;var body:some View{NavigationStack{ScrollView{VStack(alignment:.leading,spacing:18){Text("Classic Material Design 3").foregroundStyle(Color(red:.404,green:.314,blue:.643));Text("跨平台参考应用").font(.largeTitle.weight(.medium));Button("主要操作"){}.buttonStyle(.borderedProminent);GroupBox("概览"){HStack{card("Token");card("Adaptive");card("State")}}.accessibilityIdentifier("reference-overview");GroupBox("列表"){VStack{row("项目 A");row("项目 B")}}.accessibilityIdentifier("reference-list");GroupBox("表单"){VStack(alignment:.leading,spacing:12){TextField("显示名称",text:$name).textFieldStyle(.roundedBorder);Toggle("启用通知",isOn:$notifications);Button("保存"){saved=true};if saved{Text("设置已保存").foregroundStyle(.tint)}}}.accessibilityIdentifier("reference-form");GroupBox("设置"){Text("主题跟随系统；窗口变化时内容保持可读和可操作。")}.accessibilityIdentifier("reference-settings") }.padding(20)}.navigationTitle("MD3 Reference")}}@ViewBuilder private func card(_ s:String)->some View{Text(s).frame(maxWidth:.infinity,minHeight:70).background(Color.primary.opacity(.06)).clipShape(RoundedRectangle(cornerRadius:12))}@ViewBuilder private func row(_ s:String)->some View{HStack{Circle().fill(.tint.opacity(.2)).frame(width:40,height:40);VStack(alignment:.leading){Text(s);Text("辅助信息").font(.caption).foregroundStyle(.secondary)};Spacer()}.padding(.vertical,6)}}
